    '«يَٰٓأَيُّهَا ٱلۡمُدَّثِّرُ ۝ قُمۡ فَأَنذِرۡ ۝ وَرَبَّكَ فَكَبِّرۡ ۝ وَثِيَابَكَ فَطَهِّرۡ ۝ وَٱلرُّجۡزَ فَٱهۡجُرۡ ۝ وَلَا تَمۡنُن تَسۡتَكۡثِرُ ۝ وَلِرَبِّكَ فَٱصۡبِرۡ»',
    '## الأنفال (5-19)',
    '«كَمَآ أَخۡرَجَكَ رَبُّكَ مِنۢ بَيۡتِكَ بِٱلۡحَقِّ وَإِنَّ فَرِيقٗا مِّنَ ٱلۡمُؤۡمِنِينَ لَكَٰرِهُونَ ۝ يُجَٰدِلُونَكَ فِي ٱلۡحَقِّ بَعۡدَ مَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ٱلۡمَوۡتِ وَهُمۡ يَنظُرُونَ ۝ وَإِذۡ يَعِدُكُمُ ٱللَّهُ إِحۡدَى ٱلطَّآئِفَتَيۡنِ أَنَّهَا لَكُمۡ وَتَوَدُّونَ أَنَّ غَيۡرَ ذَاتِ ٱلشَّوۡكَةِ تَكُونُ لَكُمۡ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ وَيَقۡطَعَ دَابِرَ ٱلۡكَٰفِرِينَ ۝ لِيُحِقَّ ٱلۡحَقَّ وَيُبۡطِلَ ٱلۡبَٰطِلَ وَلَوۡ كَرِهَ ٱلۡمُجۡرِمُونَ ۝ إِذۡ تَسۡتَغِيثُونَ رَبَّكُمۡ فَٱسۡتَجَابَ لَكُمۡ أَنِّي مُمِدُّكُم بِأَلۡفٖ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُرۡدِفِينَ ۝ وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ وَلِتَطۡمَئِنَّ بِهِۦ قُلُوبُكُمۡۚ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ ۝ إِذۡ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةٗ مِّنۡهُ وَيُنَزِّلُ عَلَيۡكُم مِّنَ ٱلسَّمَآءِ مَآءٗ لِّيُطَهِّرَكُم بِهِۦ وَيُذۡهِبَ عَنكُمۡ رِجۡزَ ٱلشَّيۡطَٰنِ وَلِيَرۡبِطَ عَلَىٰ قُلُوبِكُمۡ وَيُثَبِّتَ بِهِ ٱلۡأَقۡدَامَ ۝ إِذۡ يُوحِي رَبُّكَ إِلَى ٱلۡمَلَٰٓئِكَةِ أَنِّي مَعَكُمۡ فَثَبِّتُواْ ٱلَّذِينَ ءَامَنُواْۚ سَأُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ فَٱضۡرِبُواْ فَوۡقَ ٱلۡأَعۡنَاقِ وَٱضۡرِبُواْ مِنۡهُمۡ كُلَّ بَنَانٖ ۝ ذَٰلِكَ بِأَنَّهُمۡ شَآقُّواْ ٱللَّهَ وَرَسُولَهُۥۚ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ۝ ذَٰلِكُمۡ فَذُوقُوهُ وَأَنَّ لِلۡكَٰفِرِينَ عَذَابَ ٱلنَّارِ ۝ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُواْ زَحۡفٗا فَلَا تُوَلُّوهُمُ ٱلۡأَدۡبَارَ ۝ وَمَن يُوَلِّهِمۡ يَوۡمَئِذٖ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفٗا لِّقِتَالٍ أَوۡ مُتَحَيِّزًا إِلَىٰ فِئَةٖ فَقَدۡ بَآءَ بِغَضَبٖ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ ۝ فَلَمۡ تَقۡتُلُوهُمۡ وَلَٰكِنَّ ٱللَّهَ قَتَلَهُمۡۚ وَمَا رَمَيۡتَ إِذۡ رَمَيۡتَ وَلَٰكِنَّ ٱللَّهَ رَمَىٰ وَلِيُبۡلِيَ ٱلۡمُؤۡمِنِينَ مِنۡهُ بَلَآءً حَسَنًاۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ ۝ ذَٰلِكُمۡ وَأَنَّ ٱللَّهَ مُوهِنُ كَيۡدِ ٱلۡكَٰفِرِينَ ۝ إِن تَسۡتَفۡتِحُواْ فَقَدۡ جَآءَكُمُ ٱلۡفَتۡحُۖ وَإِن تَنتَهُواْ فَهُوَ خَيۡرٞ لَّكُمۡۖ وَإِن تَعُودُواْ نَعُدۡ وَلَن تُغۡنِيَ عَنكُمۡ فِئَتُكُمۡ شَيۡـٔٗا وَلَوۡ كَثُرَتۡ وَأَنَّ ٱللَّهَ مَعَ ٱلۡمُؤۡمِنِينَ»',
    '## آل عمران (121-129)',
    '«وَإِذۡ غَدَوۡتَ مِنۡ أَهۡلِكَ تُبَوِّئُ ٱلۡمُؤۡمِنِينَ مَقَٰعِدَ لِلۡقِتَالِۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ ۝ إِذۡ هَمَّت طَّآئِفَتَانِ مِنكُمۡ أَن تَفۡشَلَا وَٱللَّهُ وَلِيُّهُمَاۗ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ۝ وَلَقَدۡ نَصَرَكُمُ ٱللَّهُ بِبَدۡرٖ وَأَنتُمۡ أَذِلَّةٞۖ فَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تَشۡكُرُونَ ۝ إِذۡ تَقُولُ لِلۡمُؤۡمِنِينَ أَلَن يَكۡفِيَكُمۡ أَن يُمِدَّكُمۡ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفٖ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُنزَلِينَ ۝ بَلَىٰٓۚ إِن تَصۡبِرُواْ وَتَتَّقُواْ وَيَأۡتُوكُم مِّن فَوۡرِهِمۡ هَٰذَا يُمۡدِدۡكُمۡ رَبُّكُم بِخَمۡسَةِ ءَالَٰفٖ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُسَوِّمِينَ ۝ وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ لَكُمۡ وَلِتَطۡمَئِنَّ قُلُوبُكُم بِهِۦۗ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ۝ لِيَقۡطَعَ طَرَفٗا مِّنَ ٱلَّذِينَ كَفَرُوٓاْ أَوۡ يَكۡبِتَهُمۡ فَيَنقَلِبُواْ خَآئِبِينَ ۝ لَيۡسَ لَكَ مِنَ ٱلۡأَمۡرِ شَيۡءٌ أَوۡ يَتُوبَ عَلَيۡهِمۡ أَوۡ يُعَذِّبَهُمۡ فَإِنَّهُمۡ ظَٰلِمُونَ ۝ وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ»',
    '## آل عمران (152-155)',
    '«وَلَقَدۡ صَدَقَكُمُ ٱللَّهُ وَعۡدَهُۥٓ إِذۡ تَحُسُّونَهُم بِإِذۡنِهِۦۖ حَتَّىٰٓ إِذَا فَشِلۡتُمۡ وَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَعَصَيۡتُم مِّنۢ بَعۡدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَۚ مِنكُم مَّن يُرِيدُ ٱلدُّنۡيَا وَمِنكُم مَّن يُرِيدُ ٱلۡأٓخِرَةَۚ ثُمَّ صَرَفَكُمۡ عَنۡهُمۡ لِيَبۡتَلِيَكُمۡۖ وَلَقَدۡ عَفَا عَنكُمۡۗ وَٱللَّهُ ذُو فَضۡلٍ عَلَى ٱلۡمُؤۡمِنِينَ ۝ إِذۡ تُصۡعِدُونَ وَلَا تَلۡوُۥنَ عَلَىٰٓ أَحَدٖ وَٱلرَّسُولُ يَدۡعُوكُمۡ فِيٓ أُخۡرَىٰكُمۡ فَأَثَٰبَكُمۡ غَمَّۢا بِغَمّٖ لِّكَيۡلَا تَحۡزَنُواْ عَلَىٰ مَا فَاتَكُمۡ وَلَا مَآ أَصَٰبَكُمۡۗ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ ۝ ثُمَّ أَنزَلَ عَلَيۡكُم مِّنۢ بَعۡدِ ٱلۡغَمِّ أَمَنَةٗ نُّعَاسٗا يَغۡشَىٰ طَآئِفَةٗ مِّنكُمۡۖ وَطَآئِفَةٞ قَدۡ أَهَمَّتۡهُمۡ أَنفُسُهُمۡ يَظُنُّونَ بِٱللَّهِ غَيۡرَ ٱلۡحَقِّ ظَنَّ ٱلۡجَٰهِلِيَّةِۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلۡأَمۡرِ مِن شَيۡءٖۗ قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ يُخۡفُونَ فِيٓ أَنفُسِهِم مَّا لَا يُبۡدُونَ لَكَۖ يَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَيۡءٞ مَّا قُتِلۡنَا هَٰهُنَاۗ قُل لَّوۡ كُنتُمۡ فِي بُيُوتِكُمۡ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيۡهِمُ ٱلۡقَتۡلُ إِلَىٰ مَضَاجِعِهِمۡۖ وَلِيَبۡتَلِيَ ٱللَّهُ مَا فِي صُدُورِكُمۡ وَلِيُمَحِّصَ مَا فِي قُلُوبِكُمۡۚ وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ۝ إِنَّ ٱلَّذِينَ تَوَلَّوۡاْ مِنكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ إِنَّمَا ٱسۡتَزَلَّهُمُ ٱلشَّيۡطَٰنُ بِبَعۡضِ مَا كَسَبُواْۖ وَلَقَدۡ عَفَا ٱللَّهُ عَنۡهُمۡۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ»',
    '## التوبة (40)',
    '«إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِينَ كَفَرُواْ ثَانِيَ ٱثۡنَيۡنِ إِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيۡهِ وَأَيَّدَهُۥ بِجُنُودٖ لَّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُواْ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِيَ ٱلۡعُلۡيَاۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ»',
    '## الأحزاب (9-27)',
    '«يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَآءَتۡكُمۡ جُنُودٞ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا وَجُنُودٗا لَّمۡ تَرَوۡهَاۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا ۝ إِذۡ جَآءُوكُم مِّن فَوۡقِكُمۡ وَمِنۡ أَسۡفَلَ مِنكُمۡ وَإِذۡ زَاغَتِ ٱلۡأَبۡصَٰرُ وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠ ۝ هُنَالِكَ ٱبۡتُلِيَ ٱلۡمُؤۡمِنُونَ وَزُلۡزِلُواْ زِلۡزَالٗا شَدِيدٗا ۝ وَإِذۡ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورٗا ۝ وَإِذۡ قَالَت طَّآئِفَةٞ مِّنۡهُمۡ يَٰٓأَهۡلَ يَثۡرِبَ لَا مُقَامَ لَكُمۡ فَٱرۡجِعُواْۚ وَيَسۡتَـٔۡذِنُ فَرِيقٞ مِّنۡهُمُ ٱلنَّبِيَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوۡرَةٞ وَمَا هِيَ بِعَوۡرَةٍۖ إِن يُرِيدُونَ إِلَّا فِرَارٗا ۝ وَلَوۡ دُخِلَتۡ عَلَيۡهِم مِّنۡ أَقۡطَارِهَا ثُمَّ سُئِلُواْ ٱلۡفِتۡنَةَ لَأٓتَوۡهَا وَمَا تَلَبَّثُواْ بِهَآ إِلَّا يَسِيرٗا ۝ وَلَقَدۡ كَانُواْ عَٰهَدُواْ ٱللَّهَ مِن قَبۡلُ لَا يُوَلُّونَ ٱلۡأَدۡبَٰرَۚ وَكَانَ عَهۡدُ ٱللَّهِ مَسۡـُٔولٗا ۝ قُل لَّن يَنفَعَكُمُ ٱلۡفِرَارُ إِن فَرَرۡتُم مِّنَ ٱلۡمَوۡتِ أَوِ ٱلۡقَتۡلِ وَإِذٗا لَّا تُمَتَّعُونَ إِلَّا قَلِيلٗا ۝ قُلۡ مَن ذَا ٱلَّذِي يَعۡصِمُكُم مِّنَ ٱللَّهِ إِنۡ أَرَادَ بِكُمۡ سُوٓءًا أَوۡ أَرَادَ بِكُمۡ رَحۡمَةٗۚ وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا ۝ قَدۡ يَعۡلَمُ ٱللَّهُ ٱلۡمُعَوِّقِينَ مِنكُمۡ وَٱلۡقَآئِلِينَ لِإِخۡوَٰنِهِمۡ هَلُمَّ إِلَيۡنَاۖ وَلَا يَأۡتُونَ ٱلۡبَأۡسَ إِلَّا قَلِيلًا ۝ أَشِحَّةً عَلَيۡكُمۡۖ فَإِذَا جَآءَ ٱلۡخَوۡفُ رَأَيۡتَهُمۡ يَنظُرُونَ إِلَيۡكَ تَدُورُ أَعۡيُنُهُمۡ كَٱلَّذِي يُغۡشَىٰ عَلَيۡهِ مِنَ ٱلۡمَوۡتِۖ فَإِذَا ذَهَبَ ٱلۡخَوۡفُ سَلَقُوكُم بِأَلۡسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى ٱلۡخَيۡرِۚ أُوْلَٰٓئِكَ لَمۡ يُؤۡمِنُواْ فَأَحۡبَطَ ٱللَّهُ أَعۡمَٰلَهُمۡۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا ۝ يَحۡسَبُونَ ٱلۡأَحۡزَابَ لَمۡ يَذۡهَبُواْۖ وَإِن يَأۡتِ ٱلۡأَحۡزَابُ يَوَدُّواْ لَوۡ أَنَّهُم بَادُونَ فِي ٱلۡأَعۡرَابِ يَسۡـَٔلُونَ عَنۡ أَنۢبَآئِكُمۡۖ وَلَوۡ كَانُواْ فِيكُم مَّا قَٰتَلُوٓاْ إِلَّا قَلِيلٗا ۝ لَّقَدۡ كَانَ لَكُمۡ فِي رَسُولِ ٱللَّهِ أُسۡوَةٌ حَسَنَةٞ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَ وَذَكَرَ ٱللَّهَ كَثِيرٗا ۝ وَلَمَّا رَءَا ٱلۡمُؤۡمِنُونَ ٱلۡأَحۡزَابَ قَالُواْ هَٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥۚ وَمَا زَادَهُمۡ إِلَّآ إِيمَٰنٗا وَتَسۡلِيمٗا ۝ مِّنَ ٱلۡمُؤۡمِنِينَ رِجَالٞ صَدَقُواْ مَا عَٰهَدُواْ ٱللَّهَ عَلَيۡهِۖ فَمِنۡهُم مَّن قَضَىٰ نَحۡبَهُۥ وَمِنۡهُم مَّن يَنتَظِرُۖ وَمَا بَدَّلُواْ تَبۡدِيلٗا ۝ لِّيَجۡزِيَ ٱللَّهُ ٱلصَّٰدِقِينَ بِصِدۡقِهِمۡ وَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ إِن شَآءَ أَوۡ يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا ۝ وَرَدَّ ٱللَّهُ ٱلَّذِينَ كَفَرُواْ بِغَيۡظِهِمۡ لَمۡ يَنَالُواْ خَيۡرٗاۚ وَكَفَى ٱللَّهُ ٱلۡمُؤۡمِنِينَ ٱلۡقِتَالَۚ وَكَانَ ٱللَّهُ قَوِيًّا عَزِيزٗا ۝ وَأَنزَلَ ٱلَّذِينَ ظَٰهَرُوهُم مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن صَيَاصِيهِمۡ وَقَذَفَ فِي قُلُوبِهِمُ ٱلرُّعۡبَ فَرِيقٗا تَقۡتُلُونَ وَتَأۡسِرُونَ فَرِيقٗا ۝ وَأَوۡرَثَكُمۡ أَرۡضَهُمۡ وَدِيَٰرَهُمۡ وَأَمۡوَٰلَهُمۡ وَأَرۡضٗا لَّمۡ تَطَـُٔوهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٗا»',
    '## الفتح (1-29)',
    '«إِنَّا فَتَحۡنَا لَكَ فَتۡحٗا مُّبِينٗا ۝ لِّيَغۡفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكَ وَيَهۡدِيَكَ صِرَٰطٗا مُّسۡتَقِيمٗا ۝ وَيَنصُرَكَ ٱللَّهُ نَصۡرًا عَزِيزًا ۝ هُوَ ٱلَّذِيٓ أَنزَلَ ٱلسَّكِينَةَ فِي قُلُوبِ ٱلۡمُؤۡمِنِينَ لِيَزۡدَادُوٓاْ إِيمَٰنٗا مَّعَ إِيمَٰنِهِمۡۗ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا ۝ لِّيُدۡخِلَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَيُكَفِّرَ عَنۡهُمۡ سَيِّـَٔاتِهِمۡۚ وَكَانَ ذَٰلِكَ عِندَ ٱللَّهِ فَوۡزًا عَظِيمٗا ۝ وَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡمُشۡرِكِينَ وَٱلۡمُشۡرِكَٰتِ ٱلظَّآنِّينَ بِٱللَّهِ ظَنَّ ٱلسَّوۡءِۚ عَلَيۡهِمۡ دَآئِرَةُ ٱلسَّوۡءِۖ وَغَضِبَ ٱللَّهُ عَلَيۡهِمۡ وَلَعَنَهُمۡ وَأَعَدَّ لَهُمۡ جَهَنَّمَۖ وَسَآءَتۡ مَصِيرٗا ۝ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا ۝ إِنَّآ أَرۡسَلۡنَٰكَ شَٰهِدٗا وَمُبَشِّرٗا وَنَذِيرٗا ۝ لِّتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُۚ وَتُسَبِّحُوهُ بُكۡرَةٗ وَأَصِيلًا ۝ إِنَّ ٱلَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ٱللَّهَ يَدُ ٱللَّهِ فَوۡقَ أَيۡدِيهِمۡۚ فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفۡسِهِۦۖ وَمَنۡ أَوۡفَىٰ بِمَا عَٰهَدَ عَلَيۡهُ ٱللَّهَ فَسَيُؤۡتِيهِ أَجۡرًا عَظِيمٗا ۝ سَيَقُولُ لَكَ ٱلۡمُخَلَّفُونَ مِنَ ٱلۡأَعۡرَابِ شَغَلَتۡنَآ أَمۡوَٰلُنَا وَأَهۡلُونَا فَٱسۡتَغۡفِرۡ لَنَاۚ يَقُولُونَ بِأَلۡسِنَتِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ قُلۡ فَمَن يَمۡلِكُ لَكُم مِّنَ ٱللَّهِ شَيۡـًٔا إِنۡ أَرَادَ بِكُمۡ ضَرًّا أَوۡ أَرَادَ بِكُمۡ نَفۡعَۢاۚ بَلۡ كَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرَۢا ۝ بَلۡ ظَنَنتُمۡ أَن لَّن يَنقَلِبَ ٱلرَّسُولُ وَٱلۡمُؤۡمِنُونَ إِلَىٰٓ أَهۡلِيهِمۡ أَبَدٗا وَزُيِّنَ ذَٰلِكَ فِي قُلُوبِكُمۡ وَظَنَنتُمۡ ظَنَّ ٱلسَّوۡءِ وَكُنتُمۡ قَوۡمَۢا بُورٗا ۝ وَمَن لَّمۡ يُؤۡمِنۢ بِٱللَّهِ وَرَسُولِهِۦ فَإِنَّآ أَعۡتَدۡنَا لِلۡكَٰفِرِينَ سَعِيرٗا ۝ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا ۝ سَيَقُولُ ٱلۡمُخَلَّفُونَ إِذَا ٱنطَلَقۡتُمۡ إِلَىٰ مَغَانِمَ لِتَأۡخُذُوهَا ذَرُونَا نَتَّبِعۡكُمۡۖ يُرِيدُونَ أَن يُبَدِّلُواْ كَلَٰمَ ٱللَّهِۚ قُل لَّن تَتَّبِعُونَا كَذَٰلِكُمۡ قَالَ ٱللَّهُ مِن قَبۡلُۖ فَسَيَقُولُونَ بَلۡ تَحۡسُدُونَنَاۚ بَلۡ كَانُواْ لَا يَفۡقَهُونَ إِلَّا قَلِيلٗا ۝ قُل لِّلۡمُخَلَّفِينَ مِنَ ٱلۡأَعۡرَابِ سَتُدۡعَوۡنَ إِلَىٰ قَوۡمٍ أُوْلِي بَأۡسٖ شَدِيدٖ تُقَٰتِلُونَهُمۡ أَوۡ يُسۡلِمُونَۖ فَإِن تُطِيعُواْ يُؤۡتِكُمُ ٱللَّهُ أَجۡرًا حَسَنٗاۖ وَإِن تَتَوَلَّوۡاْ كَمَا تَوَلَّيۡتُم مِّن قَبۡلُ يُعَذِّبۡكُمۡ عَذَابًا أَلِيمٗا ۝ لَّيۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجٞ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجٞ وَلَا عَلَى ٱلۡمَرِيضِ حَرَجٞۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدۡخِلۡهُ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ وَمَن يَتَوَلَّ يُعَذِّبۡهُ عَذَابًا أَلِيمٗا ۝ لَّقَدۡ رَضِيَ ٱللَّهُ عَنِ ٱلۡمُؤۡمِنِينَ إِذۡ يُبَايِعُونَكَ تَحۡتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِي قُلُوبِهِمۡ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيۡهِمۡ وَأَثَٰبَهُمۡ فَتۡحٗا قَرِيبٗا ۝ وَمَغَانِمَ كَثِيرَةٗ يَأۡخُذُونَهَاۗ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا ۝ وَعَدَكُمُ ٱللَّهُ مَغَانِمَ كَثِيرَةٗ تَأۡخُذُونَهَا فَعَجَّلَ لَكُمۡ هَٰذِهِۦ وَكَفَّ أَيۡدِيَ ٱلنَّاسِ عَنكُمۡ وَلِتَكُونَ ءَايَةٗ لِّلۡمُؤۡمِنِينَ وَيَهۡدِيَكُمۡ صِرَٰطٗا مُّسۡتَقِيمٗا ۝ وَأُخۡرَىٰ لَمۡ تَقۡدِرُواْ عَلَيۡهَا قَدۡ أَحَاطَ ٱللَّهُ بِهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٗا ۝ وَلَوۡ قَٰتَلَكُمُ ٱلَّذِينَ كَفَرُواْ لَوَلَّوُاْ ٱلۡأَدۡبَٰرَ ثُمَّ لَا يَجِدُونَ وَلِيّٗا وَلَا نَصِيرٗا ۝ سُنَّةَ ٱللَّهِ ٱلَّتِي قَدۡ خَلَتۡ مِن قَبۡلُۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبۡدِيلٗا ۝ وَهُوَ ٱلَّذِي كَفَّ أَيۡدِيَهُمۡ عَنكُمۡ وَأَيۡدِيَكُمۡ عَنۡهُم بِبَطۡنِ مَكَّةَ مِنۢ بَعۡدِ أَنۡ أَظۡفَرَكُمۡ عَلَيۡهِمۡۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا ۝ هُمُ ٱلَّذِينَ كَفَرُواْ وَصَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَٱلۡهَدۡيَ مَعۡكُوفًا أَن يَبۡلُغَ مَحِلَّهُۥۚ وَلَوۡلَا رِجَالٞ مُّؤۡمِنُونَ وَنِسَآءٞ مُّؤۡمِنَٰتٞ لَّمۡ تَعۡلَمُوهُمۡ أَن تَطَـُٔوهُمۡ فَتُصِيبَكُم مِّنۡهُم مَّعَرَّةُۢ بِغَيۡرِ عِلۡمٖۖ لِّيُدۡخِلَ ٱللَّهُ فِي رَحۡمَتِهِۦ مَن يَشَآءُۚ لَوۡ تَزَيَّلُواْ لَعَذَّبۡنَا ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابًا أَلِيمًا ۝ إِذۡ جَعَلَ ٱلَّذِينَ كَفَرُواْ فِي قُلُوبِهِمُ ٱلۡحَمِيَّةَ حَمِيَّةَ ٱلۡجَٰهِلِيَّةِ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِينَ وَأَلۡزَمَهُمۡ كَلِمَةَ ٱلتَّقۡوَىٰ وَكَانُوٓاْ أَحَقَّ بِهَا وَأَهۡلَهَاۚ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٗا ۝ لَّقَدۡ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءۡيَا بِٱلۡحَقِّۖ لَتَدۡخُلُنَّ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمۡ وَمُقَصِّرِينَ لَا تَخَافُونَۖ فَعَلِمَ مَا لَمۡ تَعۡلَمُواْ فَجَعَلَ مِن دُونِ ذَٰلِكَ فَتۡحٗا قَرِيبًا ۝ هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦۚ وَكَفَىٰ بِٱللَّهِ شَهِيدٗا ۝ مُّحَمَّدٞ رَّسُولُ ٱللَّهِۚ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلۡكُفَّارِ رُحَمَآءُ بَيۡنَهُمۡۖ تَرَىٰهُمۡ رُكَّعٗا سُجَّدٗا يَبۡتَغُونَ فَضۡلٗا مِّنَ ٱللَّهِ وَرِضۡوَٰنٗاۖ سِيمَاهُمۡ فِي وُجُوهِهِم مِّنۡ أَثَرِ ٱلسُّجُودِۚ ذَٰلِكَ مَثَلُهُمۡ فِي ٱلتَّوۡرَىٰةِۚ وَمَثَلُهُمۡ فِي ٱلۡإِنجِيلِ كَزَرۡعٍ أَخۡرَجَ شَطۡـَٔهُۥ فَـَٔازَرَهُۥ فَٱسۡتَغۡلَظَ فَٱسۡتَوَىٰ عَلَىٰ سُوقِهِۦ يُعۡجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلۡكُفَّارَۗ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ مِنۡهُم مَّغۡفِرَةٗ وَأَجۡرًا عَظِيمَۢا»',
    '## المائدة (3)',
    '«حُرِّمَتۡ عَلَيۡكُمُ ٱلۡمَيۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُواْ بِٱلۡأَزۡلَٰمِۚ ذَٰلِكُمۡ فِسۡقٌۗ ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ مِن دِينِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينٗاۚ فَمَنِ ٱضۡطُرَّ فِي مَخۡمَصَةٍ غَيۡرَ مُتَجَانِفٖ لِّإِثۡمٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ»',
  ];

  static const List<String> muhammad = [
    '## اليتيم الأمين',
    'وُلد النبي محمد ﷺ يوم الاثنين، والصحيح أنه وُلد عام الفيل، وقد حكاه إبراهيم بن المنذر الحزامي شيخ البخاري وخليفة بن خياط إجماعًا. ومات أبوه وهو حمل، وقيل بعد ولادته بأشهر، والمشهور الأول. واسترضع له في بني سعد، فأرضعته حليمة السعدية، كما رُوي بإسناد صحيح، وأقام عندها نحوًا من أربع سنين، وشُقّ عن فؤاده هناك، فردّته إلى أمه. فخرجت به أمه إلى المدينة تزور أخواله، فتوفيت بالأبواء وهي راجعة إلى مكة.',
    'فحضنته أم أيمن، وهي مولاته ورثها من أبيه، وكفله جده عبد المطلب. فلما بلغ ثماني سنين توفي جده، وأوصى به إلى عمه أبي طالب، فكفله وحاطه أتم حياطة، ونصره حين بعثه الله أعزّ نصر، مع أنه بقي على شركه حتى مات. وخرج به عمه إلى الشام في تجارة وهو ابن اثنتي عشرة سنة.',
    'وقد صانه الله من صغره، وطهّره من دنس الجاهلية ومن كل عيب، ومنحه كل خُلق جميل، حتى لم يكن يُعرف بين قومه إلا بالأمين، لما شاهدوا من طهارته وصدق حديثه وأمانته.',
    '## غار حراء',
    'ولما أراد الله رحمة العباد وإكرامهم بإرساله إلى العالمين، حُبّب إليه الخلاء، فكان يتحنّث في غار حراء كما كان يصنع متعبدو ذلك الزمان. ففاجأه الحق وهو في غار حراء في رمضان، وله من العمر أربعون سنة، فجاءه الملك فقال له: اقرأ، قال: لستُ بقارئ، فغطّه حتى بلغ منه الجهد، ثم أرسله فقال: اقرأ، قال: لست بقارئ، ثلاثًا، ثم قال له: «ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِي خَلَقَ ۝ خَلَقَ ٱلۡإِنسَٰنَ مِنۡ عَلَقٍ ۝ ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ ۝ ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ ۝ عَلَّمَ ٱلۡإِنسَٰنَ مَا لَمۡ يَعۡلَمۡ»',
    'فرجع بها رسول الله ﷺ ترجف بوادره، فأخبر خديجة رضي الله عنها وقال: قد خشيت على عقلي، فثبّتته وقالت: أبشر، كلا والله لا يخزيك الله أبدًا، إنك لتصل الرحم وتصدق الحديث وتحمل الكَلّ وتعين على نوائب الدهر.',
    'ثم مكث ما شاء الله لا يرى شيئًا وفتر عنه الوحي. ثم تبدّى له الملك بين السماء والأرض على كرسي، وثبّته وبشّره بأنه رسول الله حقًّا، فلما رآه فرِق منه وذهب إلى خديجة وقال: زمّلوني، دثّروني. فأنزل الله عليه: «يَٰٓأَيُّهَا ٱلۡمُدَّثِّرُ ۝ قُمۡ فَأَنذِرۡ ۝ وَرَبَّكَ فَكَبِّرۡ ۝ وَثِيَابَكَ فَطَهِّرۡ»',
    '## الدعوة',
    'وكانت الحال الأولى حال نبوة وإيحاء، ثم أمره الله أن ينذر قومه ويدعوهم إلى الله، فقام في طاعة الله أتمّ قيام، يدعو الكبير والصغير والحر والعبد والرجال والنساء. فاستجاب له عباد الله من كل قبيلة، وكان حائز سبقهم أبو بكر رضي الله عنه، وآزره في دين الله، فاستجاب لأبي بكر عثمان بن عفان وطلحة وسعد بن أبي وقاص.',
    'وصان الله رسوله بعمه أبي طالب، لأنه كان شريفًا مطاعًا فيهم، لا يتجاسرون على مفاجأته بشيء في أمر محمد ﷺ لما يعلمون من محبته له. وكان ﷺ يدعو إلى الله ليلًا ونهارًا سرًّا وجهارًا لا يصدّه عن ذلك صادّ ولا يرده راد، ولا تأخذه في الله لومة لائم.',
    '## الأذى والصبر',
    'ولما اشتدّ أذى المشركين على من آمن، وفتنوا منهم جماعة، كانوا يلقونهم في الحر، ويضعون الصخرة العظيمة على صدر أحدهم في شدة الحر. ومرّ أبو جهل بسُمية أم عمار وهي تُعذَّب مع زوجها وابنها، فطعنها بحربة فقتلها رضي الله عنها وعن ابنها وزوجها.',
    'فلما نُقضت الصحيفة وافق ذلك موت خديجة رضي الله عنها وموت أبي طالب، وكان بينهما ثلاثة أيام، فاشتدّ البلاء على رسول الله ﷺ من سفهاء قومه. فخرج إلى الطائف لكي يؤووه وينصروه ويمنعوه من قومه، ودعاهم إلى الله عز وجل، فلم يجيبوه إلى شيء مما طلب، وآذوه أذًى عظيمًا. فرجع عنهم، ودخل مكة في جوار المُطعِم بن عدي، وجعل يدعو إلى الله.',
    '## الإسراء',
    'وأُسري برسول الله ﷺ بجسده على الصحيح من قولي الصحابة والعلماء، من مكة إلى بيت المقدس راكبًا البراق، في صحبة جبريل عليه السلام، فنزل هناك وأمّ الأنبياء فصلى بهم. ثم عُرج به تلك الليلة إلى السماوات حتى السابعة، وفرض الله عليه الصلوات تلك الليلة.',
    '## الهجرة',
    'ولم يبقَ بمكة من المسلمين إلا رسول الله ﷺ وأبو بكر وعلي رضي الله عنهما، أقاما بأمره لهما، وقد أعدّ أبو بكر جهازه وجهاز رسول الله ﷺ منتظرًا حتى يأذن الله في الخروج. فلما كانت الليلة التي همّ فيها المشركون بالفتك برسول الله ﷺ وأرصدوا على الباب أقوامًا، خرج عليهم فلم يره منهم أحد، ثم خلص إلى بيت أبي بكر، فخرجا من خوخة في داره ليلًا، واستأجرا عبد الله بن أريقط هاديًا ماهرًا بالطريق إلى المدينة، ووعداه غار ثور بعد ثلاث. فلما حصلا في الغار عمّى الله على قريش خبرهما فلم يدروا أين ذهبا.',
    'وكان عامر بن فهيرة يريح عليهما غنمًا لأبي بكر، وكانت أسماء بنت أبي بكر تحمل لهما الزاد إلى الغار، وكان عبد الله بن أبي بكر يتسمّع ما يقال بمكة ثم يذهب إليهما به. وجاء المشركون في طلبهما حتى مرّوا على باب الغار، وأبو بكر لشدة حرصه بكى وقال: يا رسول الله لو أن أحدهم نظر موضع قدميه لرآنا، فقال له النبي ﷺ: “يا أبا بكر، ما ظنّك باثنين الله ثالثهما؟”. وذلك قوله تعالى: «إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِينَ كَفَرُواْ ثَانِيَ ٱثۡنَيۡنِ إِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيۡهِ وَأَيَّدَهُۥ بِجُنُودٖ لَّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُواْ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِيَ ٱلۡعُلۡيَاۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ»',
    'ولما كان بعد الثلاث أتى ابن أريقط بالراحلتين فركباهما، وجعلت قريش لمن جاء بواحد منهما مئة من الإبل. فلما مرّوا بحيّ مدلج بصُر بهم سراقة بن مالك، فركب جواده وسار في طلبهم. فلما قرب سمع قراءة النبي ﷺ، وأبو بكر يكثر الالتفات حذرًا عليه، وهو ﷺ لا يلتفت، فقال أبو بكر: يا رسول الله هذا سراقة قد رهقنا. فدعا عليه رسول الله ﷺ فساخت يدا فرسه في الأرض، فقال: رُميتُ، فادعوا الله لي، ولكما عليّ أن أردّ الناس عنكما. فدعا له فأُطلق، وسأل أن يكتب له كتابًا فكتب له أبو بكر، ورجع يقول للناس: قد كُفيتم ما هاهنا.',
    '## المدينة',
    'وكان الأنصار قد بلغهم مخرجه، فكانوا كل يوم يخرجون إلى الحرة ينتظرونه، فلما كان يوم الاثنين الثاني عشر من ربيع الأول على رأس ثلاث عشرة سنة من نبوته وافاهم حين اشتدّ الضحى، وكان أول من بصر به رجل من اليهود على سطح أطمه، فنادى بأعلى صوته: يا بني قيلة، هذا جدّكم الذي تنتظرون! فخرج الأنصار في سلاحهم وحيّوه بتحية النبوة. ونزل بقباء، وأسس مسجد قباء.',
    'ثم ركب بأمر الله فأدركته الجمعة في بني سالم بن عوف، ورغب إليه أهل كل دار أن ينزل عليهم، فكان يقول: “دعوها فإنها مأمورة”. فلما جاءت ناقته موضع مسجده اليوم بركت، فنزل ﷺ في دار بني النجار، فحمل أبو أيوب رضي الله عنه رحله إلى منزله. واشترى موضع المسجد، وكان مِربَدًا ليتيمين، وبناه مسجدًا، وبنى لآله حُجَرًا إلى جانبه. وآخى بين المهاجرين والأنصار، فكانوا يتوارثون بهذا الإخاء في ابتداء الإسلام.',
    '## بدر',
    'وكانت غزوة بدر الوقعة العظيمة التي فرّق الله فيها بين الحق والباطل وأعزّ الإسلام. فلما كان رمضان من السنة الثانية بلغه أن عيرًا مقبلة من الشام مع أبي سفيان تحمل أموالًا لقريش، فندب الناس للخروج إليها، وخرج في ثلاثمئة وبضعة عشر رجلًا لثمان خلون من رمضان. وكان ﷺ يقول: “اللهم إن تهلك هذه العصابة لا تُعبد في الأرض”، فذلك قوله تعالى: «إِذۡ تَسۡتَغِيثُونَ رَبَّكُمۡ فَٱسۡتَجَابَ لَكُمۡ أَنِّي مُمِدُّكُم بِأَلۡفٖ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُرۡدِفِينَ»',
    'ثم أغفى ﷺ إغفاءة ورفع رأسه وهو يقول: “أبشر يا أبا بكر، هذا جبريل على ثناياه النقع”. ومنح الله المسلمين أكتاف المشركين، فقتلوا منهم سبعين وأسروا سبعين وأخذوا غنائمهم.',
    '## أحد',
    'وفي أحد استشار رسول الله ﷺ أصحابه: أيخرج إليهم أم يمكث في المدينة؟ فبادر جماعة من فضلاء الصحابة إلى الإشارة بالخروج وألحّوا عليه، وأشار عبد الله بن أبي بن سلول بالمقام، فنهض ودخل بيته ولبس لأمته وخرج عليهم، فقالوا: يا رسول الله إن أحببت أن تمكث فافعل. فقال: “ما ينبغي لنبي إذا لبس لأمته أن يضعها حتى يقاتل”. وجعل ظهره إلى أحد، واستعمل على الرماة، وكانوا خمسين، عبد الله بن جبير، وأمره وأصحابه ألا يتغيروا من مكانهم، وأن يحفظوا ظهور المسلمين. وكانت الدولة أول النهار للمسلمين.',
    'ثم خلص المشركون إلى رسول الله ﷺ فجُرح في وجهه الكريم وكُسرت رباعيته اليمنى السفلى بحجر، وهُشمت البيضة على رأسه، ورشقه المشركون بالحجارة حتى وقع لشِقّه وسقط في حفرة، فأخذ عليّ بيده واحتضنه طلحة بن عبيد الله. وصرخ الشيطان بأعلى صوته: إن محمدًا قد قُتل، ووقع ذلك في قلوب كثير من المسلمين، وتولى أكثرهم. وأقبل ﷺ نحو المسلمين، فكان أول من عرفه تحت المغفر كعب بن مالك، فصاح: يا معشر المسلمين أبشروا، هذا رسول الله ﷺ! فأشار إليه أن اسكت، واجتمع إليه المسلمون ونهضوا معه إلى الشِّعب. واستُشهد يومئذ من المسلمين نحو السبعين.',
    'وفرّ يومئذ جماعة من الأعيان منهم عثمان بن عفان رضي الله عنه، وقد نصّ الله على العفو عنهم: «إِنَّ ٱلَّذِينَ تَوَلَّوۡاْ مِنكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ إِنَّمَا ٱسۡتَزَلَّهُمُ ٱلشَّيۡطَٰنُ بِبَعۡضِ مَا كَسَبُواْۖ وَلَقَدۡ عَفَا ٱللَّهُ عَنۡهُمۡۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ»',
    '## الخندق والحديبية',
    'وفي غزوة الخندق ابتلى الله عباده المؤمنين وزلزلهم، وثبّت الإيمان في قلوب أوليائه وأظهر ما كان يبطنه أهل النفاق. فلما سمع رسول الله ﷺ بمسير الأحزاب إليه أمر المسلمين بحفر خندق يحول بينهم وبين المدينة، بإشارة سلمان الفارسي رضي الله عنه، فعمل المسلمون فيه مبادرين. وثبت المشركون محاصرين شهرًا ولم يكن بينهم قتال لما حال الله به من الخندق. ثم أرسل الله على قريش ومن معهم الريح والخوف، فلا يثبت لهم خيمة ولا قدر ولا شيء، فترحّلوا من ليلتهم.',
    'وفي ذي القعدة من السنة السادسة خرج رسول الله ﷺ معتمرًا في ألف ونيّف، فصدّه المشركون عن الاعتمار ذلك العام، وانتهى ﷺ إلى الحديبية، وتراسل هو والمشركون حتى جاء سهيل بن عمرو فصالحه على أن يرجع عنهم عامه هذا وأن يعتمر من العام المقبل، وعلى أن يأمن الناس بينهم وبينه عشر سنين. فأجابه ﷺ إلى ما سأل لما جعل الله في ذلك من المصلحة والبركة، وكانت هذه الهدنة من أكبر الفتوحات للمسلمين كما قال عبد الله بن مسعود رضي الله عنه.',
    'ولما بلغه ﷺ أن عثمان قد قُتل دعا أصحابه إلى البيعة على القتال، فبايعوه تحت الشجرة، وأنزل الله: «لَّقَدۡ رَضِيَ ٱللَّهُ عَنِ ٱلۡمُؤۡمِنِينَ إِذۡ يُبَايِعُونَكَ تَحۡتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِي قُلُوبِهِمۡ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيۡهِمۡ وَأَثَٰبَهُمۡ فَتۡحٗا قَرِيبٗا»',
    '## فتح مكة',
    'ثم كان فتح مكة الذي أكرم الله به رسوله وأقرّ عينه به، وجعله علَمًا ظاهرًا على إعلاء كلمته وإكمال دينه. ودخل ﷺ مكة وهو راكب على ناقته وعلى رأسه المغفر، ورأسه يكاد يمسّ مقدمة الرحل من تواضعه لربه. ودعا بالمفتاح فدخل البيت وأمر بإلقاء الصور ومحوها، وأذّن بلال يومئذ على ظهر الكعبة، ثم ردّ المفتاح إلى عثمان بن طلحة وأقرّهم على السدانة. وكان الفتح لعشر بقين من رمضان.',
    '## حجة الوداع',
    'وفي السنة العاشرة خرج ﷺ من المدينة بمن معه من المسلمين ومن تجمّع من الأعراب، وصلى العصر بذي الحليفة ركعتين وبات بها. ثم سار إلى عرفة وخطب خطبة عظيمة شهدها من أصحابه نحو أربعين ألفًا، وجمع بين الظهر والعصر ثم وقف بعرفة، ثم بات بالمزدلفة، ثم رمى جمرة العقبة ونحر وحلق. وخطب ثاني يوم النحر خطبة عظيمة أيضًا، ووصّى وحذّر وأنذر، وأشهدهم على أنفسهم أنه بلّغ الرسالة.',
    'ونحن نشهد أنه بلّغ الرسالة وأدّى الأمانة ونصح الأمة ﷺ تسليمًا كثيرًا دائمًا إلى يوم الدين.',
    '## الرفيق الأعلى',
    'ثم أقبل ﷺ منصرفًا إلى المدينة وقد أكمل الله له دينه، فأقام بها بقية ذي الحجة والمحرم وصفر. ثم ابتدأ به وجعه في بيت ميمونة يوم خميس، وكان وجعًا في رأسه الكريم، فجعل مع هذا يدور على نسائه حتى شقّ عليه، فاستأذنهنّ أن يُمرَّض في بيت عائشة رضي الله عنها فأذن له، فمكث وجعًا اثني عشر يومًا. وأبو بكر رضي الله عنه يصلّي بالناس بنصّه ﷺ عليه. وقُبض ﷺ ضحى يوم الاثنين من ربيع الأول.',
  ];

